const context = $('Build Direct RAG Test Context').item.json;
const allowed = new Set(["location","price","payment_methods","offer_contents","how_it_works","personalization","delivery_access","glp1_scope","medical_boundary","acknowledgement","unsupported","objection","purchase","general_information","glp1_nutrition_support","prepared_food","post_program","ai_value","graceful_close","deferred","reminder_request","trust_credentials","human_preference","portal_support","fulfillment","support_limits","example","practical_guidance"]);
try { const raw = String($input.first().json.output || '').replace(/^\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60$/g, ''); const parsed = JSON.parse(raw); const obligations = parsed.obligations;
  if (!Array.isArray(obligations) || !obligations.length || obligations.length > 8) throw new Error('count');
  const normalized = []; const seen = new Set();
  for (const o of obligations) {
    if (!o || !allowed.has(o.type) || typeof o.evidence !== 'string' || !context.current_message.includes(o.evidence) || (o.type === 'purchase' && o.intent !== undefined && !['explicit_current_request','valid_current_confirmation'].includes(o.intent))) continue;
    const intent = o.type === 'purchase' && o.intent ? o.intent : undefined;
    const key = JSON.stringify([o.type, o.evidence, intent || null]);
    if (seen.has(key)) continue;
    seen.add(key); normalized.push({ id: 'o-' + (normalized.length + 1), type: o.type, evidence: o.evidence, ...(intent ? { intent } : {}) });
  }
  return [{ json: { ...context, obligations: normalized.length ? normalized : [{ id: 'o-1', type: 'unsupported', evidence: context.current_message }] } }];
} catch { return [{ json: { ...context, obligations: [{ id: 'o-1', type: 'unsupported', evidence: context.current_message }] } }]; }

const input = $input.first().json;
function practicalGuidance(message) {
  const text = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase();
  const guidance = /\bpoco apetito|porciones? pequenas?|comer poco\b/u.test(text) ? ['Prueba una porción pequeña con una proteína y otro componente sencillo: por ejemplo, yogurt natural con fruta, huevo con tortilla, o frijoles con queso y verduras.'] :
    /\bproteina\b/u.test(text) ? ['Como ideas sencillas de proteína puedes elegir huevo, yogurt natural, frijoles, lentejas, pollo, atún o queso, según lo que te resulte práctico.'] : ['Para una comida o snack sencillo, combina una proteína con fruta, verduras, cereal o tortilla según lo que tengas disponible.'];
  if (/\b(?:dosis|medicamento|mg|suspender|iniciar|debo bajar)\b/u.test(text)) guidance.push('Para la parte de medicamentos, consulta al profesional que te lo prescribió.');
  return guidance;
}
const claims = {"location":["Dietavity es un servicio digital.","No cuenta con atención presencial ni una sucursal para clientes."],"price":["El programa de 28 días cuesta $149 MXN.","Es un pago único, no una suscripción."],"payment_methods":["Puedes pagar con tarjeta de crédito, tarjeta de débito, OXXO o Apple Pay."],"offer_contents":["El programa incluye desayuno, comida, cena y snack para 28 días."],"how_it_works":["Después del pago verificado completas la personalización.","Luego consultas tu programa de 28 días en el portal Dietavity.","Puedes elegir iniciar desde ese día y hasta 30 días después."],"personalization":["La personalización se realiza después del pago con la información que compartes en el Setup."],"delivery_access":["El programa se consulta en el portal Dietavity después del pago verificado y de completar la personalización."],"glp1_scope":["Dietavity no vende, entrega ni prescribe medicamentos GLP-1.","Dietavity es un servicio de nutrición y programas de comidas."],"medical_boundary":["No puedo orientarte sobre iniciar, suspender o cambiar una dosis de medicamento.","Consulta al profesional que te lo prescribió."],"acknowledgement":["¡Con gusto! 😊"],"unsupported":["No tengo información confirmada para afirmar que Dietavity ofrezca eso."],"objection":["Entiendo que el precio pueda parecer alto. El programa cuesta $149 MXN por 28 días y es un pago único, sin suscripción."],"purchase":["Estamos abriendo esta modalidad de Dietavity de forma gradual. Te enviaremos por WhatsApp el enlace para completar tu compra.","$149 MXN · 28 días · pago único · sin suscripción."],"general_information":["Dietavity es un programa personalizado de alimentación de 28 días.","Incluye desayuno, comida, cena y snack para cada día.","Las comidas se adaptan a tus objetivos y preferencias."],"glp1_nutrition_support":["Dietavity ayuda a organizar comidas sencillas cuando tienes poco apetito.","El programa personalizado de 28 días incluye desayuno, comida, cena y snack, adaptados a tus objetivos y preferencias."],"prepared_food":["Dietavity no entrega comida preparada; ofrece un programa de comidas para consultar en el portal."],"post_program":["El programa actual es de 28 días; no tengo una continuidad automática confirmada para ofrecer."],"ai_value":["Dietavity organiza un programa de comidas de 28 días a partir de la información de personalización; no es una consulta humana individual."],"graceful_close":["Gracias por conocer Dietavity."],"deferred":["Claro, cuando quieras retomarlo puedes escribirnos por aquí."],"reminder_request":["Por ahora no puedo programar recordatorios automáticos, pero puedes escribirnos cuando quieras retomarlo."],"trust_credentials":["Dietavity usa inteligencia artificial; un nutriólogo humano no elabora individualmente cada programa."],"human_preference":["Entiendo tu preferencia; Dietavity no ofrece una consulta individual con un nutriólogo."],"portal_support":["Durante el programa puedes pedir por WhatsApp recetas, ideas de comidas y orientación práctica."],"fulfillment":["Después del pago verificado y de completar la personalización, el programa se consulta en el portal."],"support_limits":["El apoyo por WhatsApp es bajo demanda durante el programa; no se envían mensajes diarios proactivos."],"example":["Un ejemplo ilustrativo puede incluir desayuno, comida, cena y snack; no sustituye tu programa personalizado."],"practical_guidance":["Para una duda de alimentación o medicación, busca orientación profesional adecuada; Dietavity no da tratamiento médico."]};
const glp1LivePilotCheckoutSuppressed = true;
const resolved_obligations = input.obligations.map(obligation => {
  const validPurchase = obligation.type === 'purchase' && ['explicit_current_request','valid_current_confirmation'].includes(obligation.intent) && (obligation.intent === 'explicit_current_request' || input.commercial_state.purchase_context);
  return { obligation, resolution: obligation.type === 'unsupported' ? 'bounded_unknown' : 'resolved', permitted_claims: obligation.type === 'practical_guidance' ? practicalGuidance(input.current_message) : claims[obligation.type] || claims.unsupported, prohibited_or_boundary_claims: obligation.type === 'medical_boundary' ? ['medication_management_advice'] : obligation.type === 'glp1_scope' ? ['medication_sale_delivery_or_prescription'] : [], action_authorization: null, ...(validPurchase && glp1LivePilotCheckoutSuppressed ? { checkout_suppressed_reason: 'glp1_live_pilot' } : {}) };
});
const checkout_suppressed_reason = resolved_obligations.find(x => x.checkout_suppressed_reason)?.checkout_suppressed_reason || null;
return [{ json: { ...input, resolved_obligations, permitted_claims: resolved_obligations.flatMap(x => x.permitted_claims), authorized_action: null, checkout_suppressed_reason, pending_action: 'respond', checkout_authorized: false, checkout_authorization_type: null, checkout_question_response: null, strategy: 'direct_rag_response', buyer_signal: input.obligations.some(x => x.type === 'purchase') ? 'explicit_purchase' : 'obligation_resolution', topic: input.obligations.map(x => x.type).join(','), goal: null, offer_version: input.offer_version, inbound_message_sid: input.inbound_message_sid, events: [] } }];

const value = $('Build Direct RAG Composition Envelope').item.json; const required = value.resolved_obligations.map(x => x.obligation.id); let parsed;
try { parsed = JSON.parse(String($input.first().json.output || '').replace(/^\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60$/g, '')); } catch { parsed = null; }
const canonical = text => String(text || '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('es-MX'); const allowed = new Set(value.permitted_claims.map(canonical));
const grounded = parsed && typeof parsed.response === 'string' && parsed.response.trim().split(/(?<=[.!?])\s+/).map(canonical).filter(Boolean).every(sentence => allowed.has(sentence));
const valid = grounded && Array.isArray(parsed.covered_obligation_ids) && required.every(id => parsed.covered_obligation_ids.includes(id));
const response = valid ? parsed.response.trim() : value.resolved_obligations.flatMap(x => x.permitted_claims).join(' ');
const unsafe = /\b(?:sube|baja|aumenta|reduce|cambia|ajusta|suspende|inicia)\b.{0,50}\b(?:dosis|medicamento|mg)\b/i.test(response) || /\b(?:quieres comprar|te env[ií]o el enlace)\b/i.test(response);
const output = unsafe || !response ? value.resolved_obligations.flatMap(x => x.permitted_claims).join(' ') || 'No tengo información confirmada para responder eso.' : response;
return [{ json: { ...value, output, final_gate: { cleared: valid && !unsafe, fallback_used: !valid || unsafe, required_obligation_ids: required }, next_last_question_type: null, allow_purchase_cta: false, deterministic_reason: 'direct_rag_final_gate' } }];

const chat = $('When Chat Message Received').item.json;
if (chat.action && chat.action !== 'sendMessage') throw new Error('DIRECT_RAG_HARNESS_SEND_MESSAGE_ONLY');
if (typeof chat.chatInput !== 'string' || !chat.chatInput.trim() || chat.chatInput.length > 2000) throw new Error('DIRECT_RAG_HARNESS_TEXT_REQUIRED');
return [{ json: { session_id: "direct-rag-chat-harness:v1:synthetic-dietavity-customer", current_message: chat.chatInput.trim() } }];

const turn = $('Prepare Test Turn').item.json;
const rawHistory = $input.first().json.history;
let rows = Array.isArray(rawHistory) ? rawHistory : [];
if (typeof rawHistory === 'string') { try { rows = JSON.parse(rawHistory); } catch { rows = []; } }
const history = rows.slice(-12).map(row => ({ role: row.role === 'assistant' ? 'assistant' : 'customer', text: String(row.text || '').slice(0, 1000) }));
return [{ json: { contract_version: 'direct-rag-v2', locale: 'es-MX', session_id: turn.session_id, inbound_message_id: null, inbound_message_sid: null, current_message: turn.current_message, history, most_recent_assistant_message: history.filter(row => row.role === 'assistant').at(-1)?.text || '', customer_state: { paid: false }, commercial_state: { purchase_context: false }, offer_version: '28d-149-v1' } }];

const value = $input.first().json;
if (value.authorized_action !== null || value.checkout_authorized !== false || value.pending_action !== 'respond') throw new Error('DIRECT_RAG_HARNESS_EXTERNAL_ACTION_BLOCKED');
return [{ json: value }];

const persisted = $input.first().json;
if (Number(persisted.persisted_turn_messages) !== 2) throw new Error('DIRECT_RAG_HARNESS_TRANSCRIPT_NOT_PERSISTED');
const result = $('Final Direct RAG Customer Response Gate').item.json;
return [{ json: { output: result.output, assistant_response: result.output, test_identity: "direct-rag-chat-harness:v1:synthetic-dietavity-customer", checkout_executed: false, checkout_suppressed_reason: result.checkout_suppressed_reason || null } }];

